    vowels = "aeiou"
    shifted_vowels = "cghjklmnpqrstuvwxyz"[:5] + shifted_vowels[5:]
    encoded_message = ""
    for char in message:
        if char.isalpha():
            if char.lower() in vowels:
                encoded_char = shifted_vowels[vowels.index(char.lower())]
            elif char.islower():
                encoded_char = char.upper()
            else:
                encoded_char = char.lower()
        else:
            encoded_char = char
        encoded_message += encoded_char
